{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello जीशान जी आपको कौन सा product चाहिए?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Hello Ma'am."
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "जी बताइए आपको कौन सा product चाहिए?"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "नहीं product नहीं वो जैसे हम चप्पल की piece लेते हैं ना।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको चप्पल बनाने वाली sheet जो आमतौर पे footwear बनाने के काम आती है वही product चाहिए।"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "जी जी।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "जो wastage बच जाती है ना हमारे पास।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "तो मैं"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "नहीं मैं वो मैं बता रहा हूं पहले बात तो सुन लो।"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "जो waste seed बच जाती है वो वापस हो जाती है?"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "जी आप यह बात seller से directly discuss कर सकते हैं वह आपको सही जानकारी दे देंगे।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "पर process के लिए quantity बताना जरूरी है तो आपको कितने piece चाहिए?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "Hello, करने।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "बस कुछ details चाहिए ताकि मैं आपको सही seller से connect कर सकूं।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "आप बता दीजिए कि आपको कितनी quantity चाहिए?"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "Ma'am हमने sale करनी है।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "selling related information के लिए कृपया customer care number 5 times 96 पे call करें।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "IndiaMART सुनने के लिए धन्यवाद।"
    }
  ]
}
